			Set<ServiceSetter<object,object>> result = new();
			SETTERS_BY_RECEIVER_CLASS.put(cls, result);

			Class<object> superclass = cls.getSuperclass();
			if (superclass != null) {
				Set<ServiceSetter<object,object>> superResult = (Set) collectSettersByReceiver(superclass);
				result.addAll(superResult);
			}

			foreach (Class<object> superiface in cls.getInterfaces()) {
				Set<ServiceSetter<object,object>> superResult = (Set) collectSettersByReceiver(superiface);
				result.addAll(superResult);
